const body = $input.first().json.body || $input.first().json;

const principal = parseFloat(body.loan_amount_idr) || 500000000;
const tenureYears = parseInt(body.remaining_tenure_years) || 10;
const bank = (body.current_bank || 'BCA').toUpperCase().trim();

const defaultRates = {
  'BCA': 10.75,
  'MANDIRI': 11.25,
  'BRI': 11.00,
  'BTN': 12.00,
  'CIMB': 10.50,
  'BSI': 11.00,
  'DEFAULT': 11.00
};

const currentRate = parseFloat(body.current_interest_rate) || defaultRates[bank] || defaultRates['DEFAULT'];
const takeoverRate = 6.50;

function calcInstallment(p, ratePct, years) {
  const r = (ratePct / 100.0) / 12.0;
  const n = years * 12;
  const comp = Math.pow(1 + r, n);
  return (p * (r * comp)) / (comp - 1);
}

function formatSpokenRupiah(amount) {
  if (amount >= 1000000000) {
    return (amount / 1000000000).toFixed(1).replace('.', ' koma ') + ' miliar rupiah';
  } else if (amount >= 1000000) {
    return (amount / 1000000).toFixed(1).replace('.', ' koma ') + ' juta rupiah';
  } else {
    return Math.round(amount) + ' rupiah';
  }
}

const currentMonthly = calcInstallment(principal, currentRate, tenureYears);
const newMonthly = calcInstallment(principal, takeoverRate, tenureYears);
const monthlySavings = Math.max(0, currentMonthly - newMonthly);

const spokenCurrent = formatSpokenRupiah(currentMonthly);
const spokenNew = formatSpokenRupiah(newMonthly);
const spokenSavings = formatSpokenRupiah(monthlySavings);

const pitch = `Dengan memindahkan KPR ke rekanan Rumah123 berbunga ${takeoverRate} persen, cicilan Anda turun dari sekitar ${spokenCurrent} menjadi ${spokenNew}. Anda bisa menghemat sekitar ${spokenSavings} setiap bulannya.`;

return [{
  json: {
    status: 'success',
    current_bank: bank,
    principal_idr: principal,
    remaining_tenure_years: tenureYears,
    current_interest_rate_pct: currentRate,
    takeover_interest_rate_pct: takeoverRate,
    current_monthly_installment: Math.round(currentMonthly),
    new_monthly_installment: Math.round(newMonthly),
    monthly_savings: Math.round(monthlySavings),
    spoken_pitch: pitch,
    spoken_monthly_savings: spokenSavings
  }
}];

const body = $input.first().json.body || $input.first().json;
const phone = (body.phone_number || '').trim();
const reason = body.reason || 'User requested Do-Not-Call opt out';
const now = new Date().toISOString();

return [{
  json: {
    phone_number: phone,
    reason: reason,
    timestamp_utc: now,
    status: 'blacklisted',
    spoken_response: 'Baik, mohon maaf atas ketidaknyamanannya. Nomor Anda telah kami catat dalam daftar blokir agar tidak dihubungi kembali. Terima kasih dan selamat beraktivitas.'
  }
}];

